1	// Package codex implements the Agent interface for OpenAI's Codex CLI.
2	package codex
3	
4	import (
5		"context"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/agent"
15		"github.com/entireio/cli/cmd/entire/cli/agent/types"
16	)
17	
18	//nolint:gochecknoinits // Agent self-registration is the intended pattern
19	func init() {
20		agent.Register(agent.AgentNameCodex, NewCodexAgent)
21	}
22	
23	// CodexAgent implements the Agent interface for OpenAI's Codex CLI.
24	//
25	//nolint:revive // CodexAgent is clearer than Agent in this context
26	type CodexAgent struct{}
27	
28	// NewCodexAgent creates a new Codex agent instance.
29	func NewCodexAgent() agent.Agent {
30		return &CodexAgent{}
31	}
32	
33	// Name returns the agent registry key.
34	func (c *CodexAgent) Name() types.AgentName {
35		return agent.AgentNameCodex
36	}
37	
38	// Type returns the agent type identifier.
39	func (c *CodexAgent) Type() types.AgentType {
40		return agent.AgentTypeCodex
41	}
42	
43	// Description returns a human-readable description.
44	func (c *CodexAgent) Description() string {
45		return "Codex - OpenAI's CLI coding agent"
46	}
47	
48	// IsPreview returns true because this is a new integration.
49	func (c *CodexAgent) IsPreview() bool { return true }
